using MessagePack;
using Xunit;

[MessagePackObject]
public class ProbeDupKeyType
{
    [Key(0)]
    public string Member1 { get; set; } = string.Empty;

    [Key(0)]
    public string Member2 { get; set; } = string.Empty;

    [Key(1)]
    public int Other { get; set; }
}

public class ProbeDuplicateKeyGeneratedTypeTests
{
    [Fact]
    public void DuplicateKeyTypeRoundTripsEveryMember()
    {
        var value = new ProbeDupKeyType { Member1 = "a", Member2 = "b", Other = 1 };
        byte[] bytes = MessagePackSerializer.Serialize(value, MessagePackSerializerOptions.Standard);
        var result = MessagePackSerializer.Deserialize<ProbeDupKeyType>(bytes, MessagePackSerializerOptions.Standard);

        Assert.Equal("a", result.Member1);
        Assert.Equal("b", result.Member2);
        Assert.Equal(1, result.Other);
    }
}

