using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpCodeFixVerifier<MessagePack.SourceGenerator.Analyzers.MsgPack00xMessagePackAnalyzer, MessagePack.Analyzers.CodeFixes.MessagePackCodeFixProvider>;

public class ProbeAotDiagnosticsControlTests
{
    [Fact]
    public async Task NonSuppressedInitOnlyAndPrivateMembersStillReportAotDiagnostics()
    {
        // Control for SourceGenerationOnlyDiagnosticsAreNotReportedWhenSuppressed.
        // Same members, but WITHOUT SuppressSourceGeneration. If MsgPack016/017 are real analyzer
        // diagnostics for this input, they must appear here; otherwise the suppression test proves nothing.
        // Markup uses UseFirstDescriptor; unmarked diagnostics also count as failures.
        string input = @"
using MessagePack;

[MessagePackObject(AllowPrivate = true)]
public class Foo
{
    [Key(0)]
    private string member;

    [Key(1)]
    public string Prop1 { get; init; } = ""some default"";

    [Key(2)]
    public string Prop2 { get; set; }
}
";
        await new VerifyCS.Test
        {
            TestCode = input,
            MarkupOptions = MarkupOptions.UseFirstDescriptor,
        }.RunAsync();
    }
}
